mapper.select:
SELECT s.*, e.authenticity_status FROM kb_source s
LEFT JOIN kb_exam_source e ON e.source_id=s.id AND s.source_kind='EXAM'

    AND s.title LIKE CONCAT('%', #{title}, '%')
    AND s.source_kind=#{sourceKind}
    AND s.extraction_status=#{extractionStatus}
    AND e.authenticity_status=#{authenticityStatus}

 ORDER BY s.id DESC
